В зависимости от конкретных требований вашего проекта Defi и используемых технологий, ответ на ваш вопрос может отличаться. Однако в целом, чтобы продать токены в частном порядке ранним инвесторам и затем добавить их на панель запуска, вы можете рассмотреть следующие возможности:

1. Создание предпродажного контракта: Вам может потребоваться создать отдельный предпродажный контракт, который будет управлять продажей токенов в период предпродажи. Такой контракт обычно содержит функции, позволяющие ранним инвесторам покупать токены на предварительную цену, а также ограничивает количество токенов, которые можно купить в этот период.

Чтобы создать предпродажный контракт, вам, вероятно, потребуется использовать фреймворки, такие как OpenZeppelin, Truffle или Remix, для создания и развертывания смарт-контрактов на блокчейне. Вы можете использовать код, подобный этому, для создания предпродажного контракта:

```Solidity
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract PreSaleToken is ERC20, Ownable {

    uint256 public constant MAX_SUPPLY = 1000000; // максимальное количество токенов
    uint256 public constant PRE_SALE_SUPPLY = 500000; // количество токенов для предпродажи

    bool public isPreSaleOpen = false;

    mapping(address => uint256) public preSalePurchases;

    event PreSalePurchase(address purchaser, uint256 amount);

    constructor() ERC20("PreSaleToken", "PST") {
        _mint(msg.sender, PRE_SALE_SUPPLY);
    }

    function openPreSale() external onlyOwner {
        require(!isPreSaleOpen, "Pre-sale is already open");
        isPreSaleOpen = true;
    }

    function closePreSale() external onlyOwner {
        require(isPreSaleOpen, "Pre-sale is not open");
        isPreSaleOpen = false;
    }

    function preSalePurchase(uint256 amount) external payable whenNotPaused {
        require(isPreSaleOpen, "Pre-sale is not open");
        require(amount > 0, "Amount must be greater than zero");
        require(totalSupply() + amount <= MAX_SUPPLY, "Exceeds max supply");

        uint256 allowance = msg.sender.balance / PRE_SALE_TOKEN_PRICE; // цена токена для предпродажи
        require(allowance >= amount, "Not enough funds");

        preSalePurchases[msg.sender] += amount;
        _mint(msg.sender, amount);

        emit PreSalePurchase(msg.sender, amount);
    }

    function withdrawPreSaleFunds() external onlyOwner {
        require(address(this).balance > 0, "No funds to withdraw");

        payable(owner()).transfer(address(this).balance);
    }

    function PRE_SALE_TOKEN_PRICE() public view returns (uint256) {
        return 0.1 ether; // примерная цена токена для предпродажи
    }
}
```

